from .factory import (
    CoamCUSnapshotCollectorFactory,
    SbtsSnapshotCollectorFactory,
    CoamVDUSnapshotCollectorFactory,
    AsynchronousCoamCUSnapshotCollectorFactory,
    AsynchronousCoamVDUSnapshotCollectorFactory,
    SbtsScrelCollectorFactory,
    CoamVDUScrelCollectorFactory,
    CoamCUScrelCollectorFactory,
    AsynchronousCoamVDUScrelCollectorFactory,
    AsynchronousCoamCUScrelCollectorFactory,
    LteVduSnapshotCollectorFactory
)
from taf.collectors.core import core
from robot.utils.robottypes import is_truthy
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class snapshot(core):

    @staticmethod
    def _prepare_configuration(parameters, boolean_parameters, float_parameters):
        configuration = {}
        for key, value in parameters.items():
            if value is not None:
                if isinstance(value, dict):
                    configuration[key] = snapshot._prepare_configuration(value, boolean_parameters, float_parameters)
                elif key in float_parameters:
                    configuration[key] = float(value)
                elif key in boolean_parameters:
                    configuration[key] = is_truthy(value)
                else:
                    configuration[key] = value
        return configuration

    def _snapshot_collector(self, factory_type, parameters, boolean_parameters, float_parameters):
        configuration = self._prepare_configuration(parameters, boolean_parameters, float_parameters)
        factory = factory_type()
        logger.info(f"Creating {factory.product_class.__name__} with alias name: {configuration['name']}")
        snapshot_collector = factory.create(configuration=configuration, existing_arguments={})
        self.set_alias(parameters['name'], snapshot_collector)
        logger.info(f"{factory.product_class.__name__} created successfully")

    def create_sbts_snapshot_collector(self, name, webservice, coverage=None, force=None, timeout=None,
                                       target_file_name=None, reg_exp_filter=None, reason=None, network_cell_dns=None
                                       ):
        """
        Create Snapshot Collector for Sbts from given configuration

        :param str name: alias name of the collector
        :param dict webservice: ADMIN API setup info, see `setup_admin <https://\
                                taf-sbts-oam-coam-admin.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                interface.html#taf.sbts.oam.coam.admin.interface.admin.setup_admin>`_,
                                additionally the following parameter name abbreviations are supported:
                                 * "host" instead of "bts_host"
                                 * "port" instead of "bts_port"
                                 * "user" instead of "username"
        :param str coverage: Full or Minor snapshot scope, default: "Full"
        :param bool force: True or False to force snapshot creation, default: True
        :param int timeout:  Timeout for the operation, default: 360 secs.
        :param str reg_exp_filter: optional) since SBTS18, "regExpFilter" will be ignored if coverage is "HealthCheck"
        :param str reason: (optional) reason for the operation.
        :param list[str] network_cell_dns: (optional) list of str of network cell dist names (only for SRAN builds)
        :param str target_file_name: (optional) file name part of the path under which the zip file is
                                        stored locally during collect_collectors, default: "snapshot.zip"
        """
        self._snapshot_collector(
            factory_type=SbtsSnapshotCollectorFactory,
            parameters={
                'name': name,
                'webservice': webservice,
                'coverage': coverage,
                'force': force,
                'timeout': timeout,
                'target_file_name': target_file_name,
                'reg_exp_filter': reg_exp_filter,
                'reason': reason,
                'network_cell_dns': network_cell_dns
            },
            boolean_parameters=['force'],
            float_parameters=['timeout']
        )

    def create_coam_cu_snapshot_collector(self,
                                          name,
                                          webservice,
                                          request_timeout=None,
                                          operation_timeout=None,
                                          compressed=None,
                                          filter_regx=None,
                                          coverage=None):
        """
        Create Snapshot Collector for cOAM CU from given configuration

        :param str name: alias name of the collector
        :param dict webservice: ADMIN API setup info, see `connect_to <https://\
                                taf-gnb-oam-coam-cu.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html\
                                #taf.gnb.oam.coam.cu.interface.cu.connect_to>`_,
                                additionally the following parameter name abbreviations are supported:
                                 * "user" instead of "username"
                                 * "release" instead of "cu_version"
        :param bool compressed: (optional) if it is assigned to True, compressed all the files to one zip file.
                                       default value is True
        :param float request_timeout: timeout in seconds for sending request to OAM, defaults to 30 secs.
        :param float operation_timeout: timeout in seconds for getting snapshot, defaults to 600 secs
        :param str filter_regx: (optional) snapshot filter regular expression, default is None.
        :param str coverage: (optional) snapshot coverage, only support full or minor, default: "full"
     """
        self._snapshot_collector(factory_type=CoamCUSnapshotCollectorFactory,
                                 parameters={'name': name, 'webservice': webservice,
                                             'request_timeout': request_timeout,
                                             'operation_timeout': operation_timeout,
                                             'compressed': compressed,
                                             'filter_regx': filter_regx,
                                             'coverage': coverage},
                                 boolean_parameters=['secure', 'login_disabled'],
                                 float_parameters=['request_timeout', 'operation_timeout'])

    def create_coam_vdu_snapshot_collector(self,
                                           name,
                                           webservice,
                                           request_timeout=None,
                                           operation_timeout=None,
                                           compressed_or_not=None,
                                           filter_regx=None,
                                           coverage=None):
        """
        Create Snapshot Collector for cOAM vDU from given configuration

        :param str name: alias name of the collector
        :param dict webservice: ADMIN API setup info, see `connect_to <https://\
                                taf-gnb-oam-coam-vdu.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/\
                                interface.html#taf.gnb.oam.coam.vdu.interface.vdu.connect_to>`_,
                                additionally the following parameter name abbreviations are supported:
                                 * "user" instead of "username"
                                 * "release" instead of "vdu_version"
        :param float request_timeout: timeout in seconds for sending request to OAM, defaults to 30 secs.
        :param float operation_timeout: timeout in seconds for getting snapshot, defaults to 600 secs.
        :param bool compressed_or_not: Optional, default value is True. if it is assigned to True, compressed all the
                                       files to one zip file.
        :param str coverage: (optional) snapshot coverage, only support full or minor,
        default value is full means All logs, minor means most important logs
        :param str filter_regx: (optional) snapshot filter regular expression, default is None.
        """
        self._snapshot_collector(factory_type=CoamVDUSnapshotCollectorFactory,
                                 parameters={'name': name, 'webservice': webservice,
                                             'request_timeout': request_timeout, 'operation_timeout': operation_timeout,
                                             'compressed_or_not': compressed_or_not, 'filter_regx': filter_regx,
                                             'coverage': coverage},
                                 boolean_parameters=['secure', 'login_disabled', 'compressed_or_not'],
                                 float_parameters=['request_timeout', 'operation_timeout'])

